  ref.onDispose(() {                      // ✅ or the timer outlives the screen
    timer.cancel();
    controller.close();
  });
  return controller.stream;
});

class Cart extends Notifier<List<Item>> {
  @override
  List<Item> build() => const [];

  // ❌ the setter is never called — nothing is notified
  void addBroken(Item i) => state.add(i);

  // ❌ setter called, but with the same instance: `==` says nothing changed
  void addStillBroken(Item i) => state = state..add(i);

  // ✅ a new list every time
  void add(Item i) => state = [...state, i];

  void remove(String id) =>
      state = state.where((i) => i.id != id).toList();
}

