  final Filter initial;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final filter = ref.watch(filterNotifierProvider(initial));

    // ✅ one provider reacting to another — the callback runs after the build
    ref.listen(sessionProvider, (prev, next) {
      if (prev?.userId != next.userId) {
        ref.read(filterNotifierProvider(initial).notifier).set(Filter.none);
      }
    });

    return FilterChips(
      filter: filter,
      // ✅ writing from an event, outside the build phase
      onChanged: (f) =>
          ref.read(filterNotifierProvider(initial).notifier).set(f),
    );
  }
}

