void main() {
  test('addItem appends to the loaded cart', () async {
    // Riverpod 3; on 2.x: ProviderContainer(...) + addTearDown(container.dispose)
    final container = ProviderContainer.test(
      overrides: [cartRepoProvider.overrideWithValue(FakeCartRepo())],
    );

    // ✅ one subscription keeps the notifier alive for the whole test
    container.listen(cartProvider, (_, __) {});

    await container.read(cartProvider.future);
    await container.read(cartProvider.notifier).addItem(Item('apple'));

    expect(container.read(cartProvider).requireValue, hasLength(1));
  });

  test('❌ no listener — the mutation is thrown away', () async {
    final container = ProviderContainer.test(
      overrides: [cartRepoProvider.overrideWithValue(FakeCartRepo())],
    );

    // the await inside addItem is all the gap autoDispose needs
    await container.read(cartProvider.notifier).addItem(Item('apple'));

    expect(container.read(cartProvider).value, isNull); // rebuilt from scratch
  });
}

class StateLogger extends ProviderObserver {
  // Riverpod 3 signatures; 2.x passed (provider, prev, next, container)
  @override
  void didUpdateProvider(
    ProviderObserverContext context,
    Object? previousValue,
    Object? newValue,
  ) {
    final name = context.provider.name ?? context.provider.runtimeType.toString();
    if (!_watched.contains(name)) return; // filter, or you drown in noise
    log('$name: $previousValue -> $newValue');
  }

  @override
  void providerDidFail(
    ProviderObserverContext context,
    Object error,
    StackTrace stackTrace,
  ) {
    log('${context.provider.name} FAILED: $error');
  }

  static const _watched = {'cart', 'coupon', 'cartTotal'};
}

void main() {
  runApp(ProviderScope(
    observers: [if (kDebugMode) StateLogger()],
    child: const App(),
  ));
}

