class EditProfile extends AsyncNotifier<ProfileDraft> {
  @override
  Future<ProfileDraft> build() async {
    final userId = ref.watch(sessionProvider.select((s) => s.userId));
    final user = await ref.watch(apiProvider).me(userId);
    return ProfileDraft.fromUser(user);
  }

  void setName(String n) =>
      state = AsyncData(state.requireValue.copyWith(name: n));

  Future<void> save() async {
    // ✅ read the volatile part when it is needed, don't subscribe to it
    final token = ref.read(sessionProvider).token;
    await ref.read(apiProvider).save(state.requireValue, token);
  }
}

// ✅ or split ownership: server data reloads, the draft survives
final serverProfileProvider =
    FutureProvider<User>((ref) => ref.watch(apiProvider).me(
          ref.watch(sessionProvider.select((s) => s.userId)),
        ));

class Draft extends Notifier<ProfileDraft?> {
  @override
  ProfileDraft? build() {
    ref.listen(serverProfileProvider, (_, next) {
      // a reload is a merge decision, not an overwrite
      final user = next.value;
      if (user != null && state == null) state = ProfileDraft.fromUser(user);
    });
    return null;
  }
}

void main() {
  runApp(ProviderScope(
    // ✅ one policy for the whole app
    retry: (retryCount, error) {
      if (retryCount >= 3) return null; // give up, show the error UI

      // a failure coming from a dependency arrives wrapped
      final e = error is ProviderException ? error.exception : error;

      if (e is DioException) {
        final status = e.response?.statusCode ?? 0;
        if (status >= 400 && status < 500) return null; // terminal: our bug
        return Duration(milliseconds: 200 * (1 << retryCount));
      }
      if (e is TimeoutException || e is SocketException) {
        return Duration(milliseconds: 200 * (1 << retryCount));
      }
      return null; // parse errors and everything unknown: fail once
    },
    child: const App(),
  ));
}

