// A background isolate has its own memory: no shared state with the app.
@pragma('vm:entry-point')
Future<void> onBackgroundMessage(RemoteMessage message) async {
  final container = ProviderContainer();
  try {
    // ✅ short-lived, then thrown away; the UI sees the result via storage
    await container.read(inboxRepositoryProvider).store(message.data);
  } finally {
    container.dispose();
  }
}

